enum Coin {
    Penny,
    Nickel,
    Dime,
    Quarter,
}

fn cents(coin: Coin) -> u32 {
    match coin {
        Coin::Penny => 1,
        Coin::Nickel => 5,
        Coin::Dime => 10,
        Coin::Quarter => 25,
    }
}

fn main() {
    println!("{}", cents(Coin::Dime) + cents(Coin::Quarter));
}

fn describe(n: Option<i32>) -> String {
    match n {
        Some(0) => String::from("zero"),
        Some(x) if x < 0 => format!("negative {x}"),
        Some(1..=9) => String::from("a single digit"),
        Some(x) => format!("big number {x}"),
        None => String::from("nothing"),
    }
}

fn main() {
    println!("{}", describe(Some(0)));
    println!("{}", describe(Some(-4)));
    println!("{}", describe(Some(7)));
    println!("{}", describe(Some(250)));
    println!("{}", describe(None));
}

fn main() {
    let maybe_name = Some("Linh");
    if let Some(name) = maybe_name {
        println!("Hello, {name}");
    } else {
        println!("Hello, stranger");
    }
}

