exercise.solution:
enum Weather {
    Sun,
    Rain,
    Snow,
}

fn advice(w: Weather) -> &'static str {
    match w {
        Weather::Sun => "Wear sunscreen",
        Weather::Rain => "Take an umbrella",
        Weather::Snow => "Wear a warm coat",
    }
}

fn main() {
    println!("{}", advice(Weather::Rain));
}
